INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation)
VALUES
('ภาษาอังกฤษ', 'ป.4', '[ต 1.1 ป.4/1] Classroom Instructions and Commands', 'easy', 'mcq', 'When the teacher says, "Open your book to page 25," what should you do?', '["ปิดหนังสือหน้าที่ 25","เปิดหนังสือหน้าที่ 25","เขียนชื่อในหน้าที่ 25","ส่งหนังสือคืนครู"]'::jsonb, 1, '"Open your book to page 25" แปลว่า ให้เปิดหนังสือไปที่หน้าที่ 25'),
('ภาษาอังกฤษ', 'ป.4', '[ต 1.1 ป.4/1] Classroom Commands', 'easy', 'mcq', 'What is the opposite of the command "Stand up"?', '["Sit down","Turn around","Look at the board","Be quiet"]'::jsonb, 0, '"Stand up" แปลว่า ยืนขึ้น คำตรงข้ามคือ "Sit down" ซึ่งแปลว่า นั่งลง'),
('ภาษาอังกฤษ', 'ป.4', '[ต 1.1 ป.4/2] Phonics: Short and Long Vowels', 'medium', 'mcq', 'Which word has the same vowel sound as "cake" /eɪ/?', '["cat","lake","car","ball"]'::jsonb, 1, 'คำว่า "lake" ออกเสียงสระเอ (long a sound: /eɪ/) เหมือนกับคำว่า "cake"'),
('ภาษาอังกฤษ', 'ป.4', '[ต 1.1 ป.4/2] Phonics: Consonant Blends', 'easy', 'mcq', 'Which word begins with the blend sound /fl/?', '["frog","flag","drum","clock"]'::jsonb, 1, '"flag" ขึ้นต้นด้วยพยัญชนะควบกล้ำ fl- (ฟล)'),
('ภาษาอังกฤษ', 'ป.4', '[ต 1.1 ป.4/3] Signs and Public Symbols', 'easy', 'mcq', 'You see a sign with a cigarette and a red cross over it. What does it mean?', '["No parking","No smoking","No food or drink","No taking photos"]'::jsonb, 1, 'ป้ายรูปบุหรี่มีแถบกากบาทสีแดง หมายถึง "No smoking" (ห้ามสูบบุหรี่)'),
('ภาษาอังกฤษ', 'ป.4', '[ต 1.1 ป.4/3] Library Signs', 'easy', 'mcq', 'Which sign is most suitable for a school library?', '["Please be quiet","Danger! Do not enter","Turn right","Drive fast"]'::jsonb, 0, 'ในห้องสมุดควรมีป้าย "Please be quiet" (กรุณาเงียบ / งดใช้เสียง)'),
('ภาษาอังกฤษ', 'ป.4', '[ต 1.1 ป.4/4] Reading Short Comprehension', 'medium', 'mcq', 'Read the text: "Anna has a brown puppy named Lucky. Lucky likes to run in the park and fetch a small red ball." What is Lucky?', '["A kitten","A puppy","A bird","A rabbit"]'::jsonb, 1, 'ในเนื้อเรื่องระบุชัดเจนว่า "Anna has a brown puppy named Lucky."'),
('ภาษาอังกฤษ', 'ป.4', '[ต 1.1 ป.4/4] Reading Details', 'medium', 'mcq', 'From the text about Lucky: What color is the ball that Lucky likes to fetch?', '["Yellow","Green","Red","Blue"]'::jsonb, 2, 'ในเนื้อเรื่องระบุว่า "...and fetch a small red ball." ดังนั้นลูกบอลเป็นสีแดง'),
('ภาษาอังกฤษ', 'ป.4', '[ต 1.1 ป.4/2] Rhyming Words', 'easy', 'mcq', 'Which word rhymes with "sun"?', '["fun","sit","top","hot"]'::jsonb, 0, '"sun" (/sʌn/) มีเสียงสัมผัสสระและตัวสะกดตรงกับคำว่า "fun" (/fʌn/)'),
('ภาษาอังกฤษ', 'ป.4', '[ต 1.1 ป.4/3] Traffic Signs', 'easy', 'mcq', 'What does a red octagonal sign with the word "STOP" instruct drivers to do?', '["Go faster","Turn around","Stop the vehicle completely","Park here"]'::jsonb, 2, 'ป้าย STOP สั่งให้ผู้ขับขี่หยุดรถโดยสมบูรณ์ก่อนเพื่อความปลอดภัย'),
('ภาษาอังกฤษ', 'ป.4', '[ต 1.1 ป.4/2] Digraph Sounds: /sh/ and /ch/', 'medium', 'mcq', 'Which word contains the /tʃ/ sound as in "chair"?', '["ship","chocolate","shoe","fish"]'::jsonb, 1, '"chocolate" ออกเสียงพยัญชนะต้น ch- (/tʃ/) เหมือนคำว่า "chair"'),
('ภาษาอังกฤษ', 'ป.4', '[ต 1.1 ป.4/4] Understanding Timetables', 'medium', 'mcq', 'Look at Tom''s timetable: "09:00 - English, 10:00 - Math, 11:00 - Science, 12:00 - Lunch." What subject does Tom study at 10:00?', '["English","Math","Science","Art"]'::jsonb, 1, 'จากตารางเรียน เวลา 10:00 น. ทอมเรียนวิชาคณิตศาสตร์ (Math)'),
('ภาษาอังกฤษ', 'ป.4', '[ต 1.2 ป.4/1] Greetings and How Are You', 'easy', 'mcq', 'A: "Good morning, Tom! How are you today?"
B: "________, thank you. And you?"', '["I am 10 years old","I am fine","My name is Tom","I am from Thailand"]'::jsonb, 1, 'เมื่อมีคนถามว่า "How are you today?" คำตอบมาตรฐานคือ "I am fine / I am good, thank you."'),
('ภาษาอังกฤษ', 'ป.4', '[ต 1.2 ป.4/1] Introductions', 'easy', 'mcq', 'A: "Nice to meet you, Lisa."
B: "____________________"', '["Good night","Nice to meet you, too","Goodbye","You are welcome"]'::jsonb, 1, 'เมื่อผู้อื่นพูดว่า "Nice to meet you." ควรตอบกลับว่า "Nice to meet you, too."'),
('ภาษาอังกฤษ', 'ป.4', '[ต 1.2 ป.4/2] Asking for Permission', 'medium', 'mcq', 'Student: "May I go to the restroom, please?"
Teacher: "________"', '["Yes, you may.","No, thank you.","I am sorry.","You are tall."]'::jsonb, 0, 'เมื่อขออนุญาตด้วย "May I...?" คุณครูอนุญาตจะตอบว่า "Yes, you may." หรือ "Sure."'),
('ภาษาอังกฤษ', 'ป.4', '[ต 1.2 ป.4/2] Offering Help', 'medium', 'mcq', 'A: "Can I help you carry these heavy books?"
B: "____________________"', '["No, I am not.","Thank you very much. That is very kind of you.","I am hungry.","It is 5 o''clock."]'::jsonb, 1, 'เมื่อมีผู้เสนอความช่วยเหลือและเราต้องการรับ ควรตอบขอบคุณอย่างสุภาพว่า "Thank you very much."'),
('ภาษาอังกฤษ', 'ป.4', '[ต 1.2 ป.4/3] Expressing Likes and Dislikes', 'easy', 'mcq', 'A: "Do you like apples?"
B: "Yes, ________. They are delicious."', '["I do","I am","I can","I like not"]'::jsonb, 0, 'คำถามที่ขึ้นต้นด้วย "Do you...?" เวลาตอบรับแบบสั้นจะใช้ "Yes, I do."'),
('ภาษาอังกฤษ', 'ป.4', '[ต 1.2 ป.4/3] Asking About Food Preferences', 'medium', 'mcq', 'A: "What is your favorite fruit?"
B: "My favorite fruit is ________."', '["pizza","mango","fried rice","milk"]'::jsonb, 1, 'ผลไม้ (fruit) ในตัวเลือกมีเพียงอย่างเดียวคือ "mango" (มะม่วง)'),
('ภาษาอังกฤษ', 'ป.4', '[ต 1.2 ป.4/4] Asking Feelings and Emotions', 'easy', 'mcq', 'Look at the picture of a boy drinking water after playing sports. How does he feel?', '["He is thirsty.","He is cold.","He is sleepy.","He is angry."]'::jsonb, 0, 'คนที่ดื่มน้ำหลังเล่นกีฬา คือรู้สึกกระหายน้ำ หรือ "thirsty"'),
('ภาษาอังกฤษ', 'ป.4', '[ต 1.2 ป.4/4] Expressing Feelings', 'easy', 'mcq', 'A: "Why are you smiling?"
B: "Because I am very ________ today. It is my birthday!"', '["sad","happy","tired","sick"]'::jsonb, 1, 'ในวันเกิดและกำลังยิ้ม แสดงถึงความรู้สึกมีความสุข หรือ "happy"'),
('ภาษาอังกฤษ', 'ป.4', '[ต 1.2 ป.4/1] Saying Goodbye', 'easy', 'mcq', 'A: "See you tomorrow, Jack!"
B: "________, see you!"', '["Good morning","Goodbye","Good afternoon","Hello"]'::jsonb, 1, 'เมื่อเพื่อนบอกลาว่า "See you tomorrow!" เราควรตอบว่า "Goodbye, see you!"'),
('ภาษาอังกฤษ', 'ป.4', '[ต 1.2 ป.4/2] Polite Responses (You''re welcome)', 'easy', 'mcq', 'A: "Thank you for lending me your pencil."
B: "____________________"', '["You are welcome.","I am sorry.","Never.","No way."]'::jsonb, 0, 'เมื่อมีคนกล่าว "Thank you" คำตอบรับตามมารยาทคือ "You are welcome."'),
('ภาษาอังกฤษ', 'ป.4', '[ต 1.2 ป.4/2] Apologizing (Sorry)', 'easy', 'mcq', 'When you accidentally step on someone''s foot, what should you say?', '["Congratulations!","I am so sorry.","Thank you!","Excuse me, where is the toilet?"]'::jsonb, 1, 'เมื่อเผลอเหยียบเท้าผู้อื่นโดยไม่ได้ตั้งใจ ควรกล่าวขอโทษว่า "I am so sorry."'),
('ภาษาอังกฤษ', 'ป.4', '[ต 1.2 ป.4/3] Asking for Prices', 'medium', 'mcq', 'Customer: "________ is this school bag?"
Shopkeeper: "It is 250 baht."', '["How many","How much","How old","How long"]'::jsonb, 1, 'การถามราคาสิ่งของ ใช้คำถามว่า "How much is...?"'),
('ภาษาอังกฤษ', 'ป.4', '[ต 1.3 ป.4/1] Telling Time', 'easy', 'mcq', 'The clock shows the short hand at 3 and the long hand at 12. What time is it?', '["It is three o''clock.","It is twelve o''clock.","It is half past three.","It is three thirty."]'::jsonb, 0, 'เข็มสั้นชี้เลข 3 เข็มยาวชี้เลข 12 คือเวลา 3 นาฬิกาตรง ("It is three o''clock.")'),
('ภาษาอังกฤษ', 'ป.4', '[ต 1.3 ป.4/1] Telling Time (Half past)', 'medium', 'mcq', 'What time is 08:30 in words?', '["It is eight o''clock.","It is half past eight.","It is eight fifteen.","It is half past nine."]'::jsonb, 1, 'เวลา 08:30 คือ "half past eight" (ผ่านแปดโมงมาครึ่งชั่วโมง)'),
('ภาษาอังกฤษ', 'ป.4', '[ต 1.3 ป.4/1] Describing Appearance', 'medium', 'mcq', 'Mary has long black hair and big brown eyes. Which sentence describes Mary correctly?', '["She has short blonde hair.","She has long black hair.","She is short and fat.","Her eyes are blue."]'::jsonb, 1, 'จากข้อความระบุชัดเจนว่า "She has long black hair..."'),
('ภาษาอังกฤษ', 'ป.4', '[ต 1.3 ป.4/1] Describing Animals', 'easy', 'mcq', 'It is a large animal. It has a long trunk and big ears. What animal is it?', '["A giraffe","A tiger","An elephant","A monkey"]'::jsonb, 2, 'สัตว์ที่มีงวงยาว (trunk) และใบหูใหญ่ คือช้าง (an elephant)'),
('ภาษาอังกฤษ', 'ป.4', '[ต 1.3 ป.4/2] Daily Routines', 'easy', 'mcq', 'What do you do right after you wake up in the morning?', '["I go to bed.","I brush my teeth and wash my face.","I do my homework at night.","I play football in the rain."]'::jsonb, 1, 'หลังตื่นนอนตอนเช้า กิจวัตรปกติคือการแปรงฟันและล้างหน้า ("brush my teeth and wash my face")'),
('ภาษาอังกฤษ', 'ป.4', '[ต 1.3 ป.4/2] School Subjects', 'easy', 'mcq', 'In which subject do you learn about numbers, addition, and shapes?', '["English","Music","Mathematics (Math)","Physical Education (PE)"]'::jsonb, 2, 'วิชาที่เรียนเกี่ยวกับตัวเลข การบวก และรูปทรง คือคณิตศาสตร์ (Math / Mathematics)'),
('ภาษาอังกฤษ', 'ป.4', '[ต 1.3 ป.4/1] Days of the Week', 'easy', 'mcq', 'Which day comes right after Tuesday?', '["Monday","Wednesday","Thursday","Friday"]'::jsonb, 1, 'วันพุธ (Wednesday) มาต่อจากวันอังคาร (Tuesday) เสมอ'),
('ภาษาอังกฤษ', 'ป.4', '[ต 1.3 ป.4/1] Months of the Year', 'medium', 'mcq', 'Which is the twelfth (12th) month of the year?', '["October","November","December","January"]'::jsonb, 2, 'เดือนที่ 12 ของปีคือเดือนธันวาคม (December)'),
('ภาษาอังกฤษ', 'ป.4', '[ต 1.3 ป.4/1] Describing Weather', 'easy', 'mcq', 'The sun is shining brightly and the sky is clear. What is the weather like?', '["It is rainy.","It is snowy.","It is sunny.","It is stormy."]'::jsonb, 2, 'แดดออกจ้า ท้องฟ้าแจ่มใส คือสภาพอากาศ "sunny"'),
('ภาษาอังกฤษ', 'ป.4', '[ต 1.3 ป.4/1] Rooms in a House', 'easy', 'mcq', 'Where do people usually cook food and prepare meals in a house?', '["In the bedroom","In the kitchen","In the bathroom","In the garage"]'::jsonb, 1, 'ห้องครัว (kitchen) คือห้องสำหรับปรุงอาหาร'),
('ภาษาอังกฤษ', 'ป.4', '[ต 1.3 ป.4/2] Occupations and Jobs', 'easy', 'mcq', 'A person who cures sick people and works in a hospital is a ________.', '["teacher","doctor","cook","farmer"]'::jsonb, 1, 'ผู้ที่รักษาคนป่วยในโรงพยาบาลคือคุณหมอ (doctor)'),
('ภาษาอังกฤษ', 'ป.4', '[ต 1.3 ป.4/2] Occupations: Teacher', 'easy', 'mcq', 'A person who teaches students at school is a ________.', '["pilot","police officer","teacher","firefighter"]'::jsonb, 2, 'ผู้สอนหนังสือนักเรียนในโรงเรียนคือคุณครู (teacher)'),
('ภาษาอังกฤษ', 'ป.4', '[ต 2.1 ป.4/1] Festivals: Christmas Day', 'easy', 'mcq', 'On Christmas Day (December 25th), who brings presents to children down the chimney?', '["Santa Claus","The Easter Bunny","A snowman","Peter Pan"]'::jsonb, 0, 'ซานตาคลอส (Santa Claus) เป็นสัญลักษณ์ของเทศกาลคริสต์มาสที่นำของขวัญมามอบให้เด็กๆ'),
('ภาษาอังกฤษ', 'ป.4', '[ต 2.1 ป.4/1] Festivals: Halloween', 'easy', 'mcq', 'On October 31st (Halloween), children dress up in costumes and say: "________ or treat!"', '["Play","Trick","Sing","Dance"]'::jsonb, 1, 'ในเทศกาลฮาโลวีน เด็กๆ จะแต่งกายแฟนซีไปเคาะประตูบ้านเพื่อขอขนมด้วยคำพูดว่า "Trick or treat!"'),
('ภาษาอังกฤษ', 'ป.4', '[ต 2.1 ป.4/1] Symbols of Halloween', 'medium', 'mcq', 'What vegetable is carved into a Jack-o''-lantern for Halloween?', '["A carrot","A pumpkin","A tomato","A potato"]'::jsonb, 1, 'ฟักทอง (pumpkin) ถูกนำมาแกะสลักเป็นตะเกียงหน้าผีที่เรียกว่า Jack-o''-lantern'),
('ภาษาอังกฤษ', 'ป.4', '[ต 2.1 ป.4/1] New Year Celebrations', 'easy', 'mcq', 'What do people say to greet each other on January 1st?', '["Merry Christmas!","Happy New Year!","Happy Halloween!","Happy Birthday!"]'::jsonb, 1, 'ในวันที่ 1 มกราคม (วันปีใหม่สากล) ผู้คนจะทักทายอวยพรกันว่า "Happy New Year!"'),
('ภาษาอังกฤษ', 'ป.4', '[ต 2.1 ป.4/2] Western Etiquette and Politeness', 'medium', 'mcq', 'In English culture, which word is used to show politeness when asking for something?', '["Please","Now","Quickly","Give"]'::jsonb, 0, 'คำว่า "Please" ใช้กำกับเมื่อขอร้องหรือสั่งซื้อสิ่งใดเพื่อให้สุภาพ นอบน้อม'),
('ภาษาอังกฤษ', 'ป.4', '[ต 2.1 ป.4/2] Table Manners', 'easy', 'mcq', 'What should you do while chewing food at the dining table?', '["Talk loudly with your mouth open","Keep your mouth closed and do not speak with food in your mouth","Sing a song","Spit food on the floor"]'::jsonb, 1, 'มารยาทบนโต๊ะอาหารสากลคือการเคี้ยวอาหารโดยปิดปากและไม่พูดคุยขณะยังมีอาหารเต็มปาก'),
('ภาษาอังกฤษ', 'ป.4', '[ต 4.1 ป.4/1] Pronouns: Subject Pronouns', 'easy', 'mcq', 'Peter is playing football. ________ is very fast.', '["She","He","They","It"]'::jsonb, 1, 'Peter เป็นผู้ชาย สรรพนามบุรุษที่ 3 เอกพจน์เพศชายคือ "He"'),
('ภาษาอังกฤษ', 'ป.4', '[ต 4.1 ป.4/1] Pronouns: Plural Subject Pronouns', 'easy', 'mcq', 'Tom and I are in Grade 4. ________ are classmates.', '["He","We","They","You"]'::jsonb, 1, 'Tom and I (ทอมและฉัน) มีผู้พูดรวมอยู่ด้วย จัดเป็นสรรพนามพหูพจน์ "We" (พวกเรา)'),
('ภาษาอังกฤษ', 'ป.4', '[ต 4.1 ป.4/1] Possessive Adjectives', 'medium', 'mcq', 'I have a new bicycle. ________ bicycle is red.', '["My","His","Her","Your"]'::jsonb, 0, 'สรรพนามแสดงความเป็นเจ้าของของ "I" คือ "My" (จักรยานของฉัน)'),
('ภาษาอังกฤษ', 'ป.4', '[ต 4.1 ป.4/1] Verb to be: Present Simple', 'easy', 'mcq', 'She ________ a student at Kampai School.', '["am","is","are","be"]'::jsonb, 1, 'ประธานเอกพจน์บุรุษที่ 3 (He, She, It) ใช้กริยา "is"'),
('ภาษาอังกฤษ', 'ป.4', '[ต 4.1 ป.4/1] Verb to be: Plural', 'easy', 'mcq', 'They ________ good friends.', '["is","are","am","was"]'::jsonb, 1, 'ประธานพหูพจน์ (They, We, You) ใช้กับกริยา "are"'),
('ภาษาอังกฤษ', 'ป.4', '[ต 4.1 ป.4/1] Verb to have: have / has', 'medium', 'mcq', 'A bird ________ two wings.', '["have","has","having","is"]'::jsonb, 1, 'ประธานเอกพจน์ "A bird" 1 ตัว ใช้ "has" ส่วนพหูพจน์หรือ I/You ใช้ "have"'),
('ภาษาอังกฤษ', 'ป.4', '[ต 4.1 ป.4/1] Verb to have: Plural', 'easy', 'mcq', 'We ________ five pencils in the pencil case.', '["has","have","is","are"]'::jsonb, 1, 'ประธาน "We" ใช้ "have"'),
('ภาษาอังกฤษ', 'ป.4', '[ต 4.1 ป.4/1] Present Simple Tense: Subject-Verb Agreement', 'medium', 'mcq', 'He ________ to school by bus every day.', '["go","goes","going","went"]'::jsonb, 1, 'ใน Present Simple Tense เมื่อประธานเป็น He, She, It กริยาต้องเติม -s หรือ -es (go -> goes)'),
('ภาษาอังกฤษ', 'ป.4', '[ต 4.1 ป.4/1] Present Simple Tense: Plural Subject', 'easy', 'mcq', 'The students ________ milk every morning.', '["drinks","drink","drinking","drank"]'::jsonb, 1, 'ประธานพหูพจน์ "The students" กริยาใช้รูปเดิม ไม่ต้องเติม -s (drink)'),
('ภาษาอังกฤษ', 'ป.4', '[ต 4.1 ป.4/1] Present Continuous Tense', 'medium', 'mcq', 'Look! The cat is ________ on the sofa right now.', '["sleep","sleeping","sleeps","slept"]'::jsonb, 1, 'Present Continuous (is/am/are + V-ing) ใช้บรรยายเหตุการณ์ที่กำลังดำเนินอยู่ขณะนี้ ("is sleeping")'),
('ภาษาอังกฤษ', 'ป.4', '[ต 4.1 ป.4/1] Present Continuous Tense: Plural', 'medium', 'mcq', 'The children ________ a song in the music room now.', '["is singing","are singing","sing","sings"]'::jsonb, 1, 'ประธาน "The children" เป็นพหูพจน์ จึงใช้โครงสร้าง "are singing"'),
('ภาษาอังกฤษ', 'ป.4', '[ต 4.1 ป.4/1] Prepositions of Place: in / on / under', 'easy', 'mcq', 'The ball is ________ the table on the floor.', '["under","in","on","above"]'::jsonb, 0, 'ลูกบอลวางอยู่ใต้โต๊ะบนพื้น ใช้คำบุพบท "under" (ใต้)'),
('ภาษาอังกฤษ', 'ป.4', '[ต 4.1 ป.4/1] Prepositions of Place: next to / behind', 'medium', 'mcq', 'The cat is hiding ________ the door so no one can see it.', '["behind","on","between","under"]'::jsonb, 0, 'แอบอยู่ "หลังประตู" เพื่อไม่ให้ใครมองเห็น ใช้ "behind" (ด้านหลัง)'),
('ภาษาอังกฤษ', 'ป.4', '[ต 4.1 ป.4/1] WH-Question Words: Where', 'easy', 'mcq', 'A: "________ do you live?"
B: "I live in Khon Kaen."', '["Who","Where","When","Why"]'::jsonb, 1, 'การถามถึงสถานที่หรือที่อยู่อาศัย ใช้ Question word ว่า "Where" (ที่ไหน)'),
('ภาษาอังกฤษ', 'ป.4', '[ต 4.1 ป.4/1] WH-Question Words: When', 'easy', 'mcq', 'A: "________ is your birthday?"
B: "It is on May 15th."', '["When","What","Where","Who"]'::jsonb, 0, 'การถามถึงเวลาหรือวันเดือนปี ใช้คำว่า "When" (เมื่อไร)'),
('ภาษาอังกฤษ', 'ป.4', '[ต 4.1 ป.4/1] WH-Question Words: Who', 'easy', 'mcq', 'A: "________ is that tall man?"
B: "He is our English teacher, Mr. David."', '["What","Where","Who","How"]'::jsonb, 2, 'การถามถึงบุคคล ใช้ Question word ว่า "Who" (ใคร)'),
('ภาษาอังกฤษ', 'ป.4', '[ต 4.1 ป.4/1] How many (Countable Nouns)', 'medium', 'mcq', 'A: "________ apples are there in the basket?"
B: "There are six apples."', '["How much","How many","How old","How tall"]'::jsonb, 1, 'การถามจำนวนของคำนามนับได้พหูพจน์ (apples) ใช้ "How many"'),
('ภาษาอังกฤษ', 'ป.4', '[ต 4.1 ป.4/1] Singular and Plural Nouns', 'easy', 'mcq', 'What is the correct plural form of "box"?', '["boxs","boxes","boxies","boxen"]'::jsonb, 1, 'คำนามที่ลงท้ายด้วย -x เมื่อเปลี่ยนเป็นพหูพจน์ต้องเติม -es (box -> boxes)');

INSERT INTO public.exam_sets (title, subject, grade, questions, time_limit_minutes, pass_threshold_pct, pin_code, is_active)
VALUES ('แบบทดสอบมาตรฐาน วิชาภาษาอังกฤษ ป.4 (20 ข้อ)', 'ภาษาอังกฤษ', 'ป.4', '[{"subject":"ภาษาอังกฤษ","grade":"ป.4","topic":"[ต 1.1 ป.4/1] Classroom Instructions and Commands","difficulty":"easy","question_type":"mcq","question_text":"When the teacher says, \"Open your book to page 25,\" what should you do?","options":["ปิดหนังสือหน้าที่ 25","เปิดหนังสือหน้าที่ 25","เขียนชื่อในหน้าที่ 25","ส่งหนังสือคืนครู"],"answer":1,"explanation":"\"Open your book to page 25\" แปลว่า ให้เปิดหนังสือไปที่หน้าที่ 25"},{"subject":"ภาษาอังกฤษ","grade":"ป.4","topic":"[ต 1.1 ป.4/1] Classroom Commands","difficulty":"easy","question_type":"mcq","question_text":"What is the opposite of the command \"Stand up\"?","options":["Sit down","Turn around","Look at the board","Be quiet"],"answer":0,"explanation":"\"Stand up\" แปลว่า ยืนขึ้น คำตรงข้ามคือ \"Sit down\" ซึ่งแปลว่า นั่งลง"},{"subject":"ภาษาอังกฤษ","grade":"ป.4","topic":"[ต 1.1 ป.4/2] Phonics: Short and Long Vowels","difficulty":"medium","question_type":"mcq","question_text":"Which word has the same vowel sound as \"cake\" /eɪ/?","options":["cat","lake","car","ball"],"answer":1,"explanation":"คำว่า \"lake\" ออกเสียงสระเอ (long a sound: /eɪ/) เหมือนกับคำว่า \"cake\""},{"subject":"ภาษาอังกฤษ","grade":"ป.4","topic":"[ต 1.1 ป.4/2] Phonics: Consonant Blends","difficulty":"easy","question_type":"mcq","question_text":"Which word begins with the blend sound /fl/?","options":["frog","flag","drum","clock"],"answer":1,"explanation":"\"flag\" ขึ้นต้นด้วยพยัญชนะควบกล้ำ fl- (ฟล)"},{"subject":"ภาษาอังกฤษ","grade":"ป.4","topic":"[ต 1.1 ป.4/3] Signs and Public Symbols","difficulty":"easy","question_type":"mcq","question_text":"You see a sign with a cigarette and a red cross over it. What does it mean?","options":["No parking","No smoking","No food or drink","No taking photos"],"answer":1,"explanation":"ป้ายรูปบุหรี่มีแถบกากบาทสีแดง หมายถึง \"No smoking\" (ห้ามสูบบุหรี่)"},{"subject":"ภาษาอังกฤษ","grade":"ป.4","topic":"[ต 1.1 ป.4/3] Library Signs","difficulty":"easy","question_type":"mcq","question_text":"Which sign is most suitable for a school library?","options":["Please be quiet","Danger! Do not enter","Turn right","Drive fast"],"answer":0,"explanation":"ในห้องสมุดควรมีป้าย \"Please be quiet\" (กรุณาเงียบ / งดใช้เสียง)"},{"subject":"ภาษาอังกฤษ","grade":"ป.4","topic":"[ต 1.1 ป.4/4] Reading Short Comprehension","difficulty":"medium","question_type":"mcq","question_text":"Read the text: \"Anna has a brown puppy named Lucky. Lucky likes to run in the park and fetch a small red ball.\" What is Lucky?","options":["A kitten","A puppy","A bird","A rabbit"],"answer":1,"explanation":"ในเนื้อเรื่องระบุชัดเจนว่า \"Anna has a brown puppy named Lucky.\""},{"subject":"ภาษาอังกฤษ","grade":"ป.4","topic":"[ต 1.1 ป.4/4] Reading Details","difficulty":"medium","question_type":"mcq","question_text":"From the text about Lucky: What color is the ball that Lucky likes to fetch?","options":["Yellow","Green","Red","Blue"],"answer":2,"explanation":"ในเนื้อเรื่องระบุว่า \"...and fetch a small red ball.\" ดังนั้นลูกบอลเป็นสีแดง"},{"subject":"ภาษาอังกฤษ","grade":"ป.4","topic":"[ต 1.1 ป.4/2] Rhyming Words","difficulty":"easy","question_type":"mcq","question_text":"Which word rhymes with \"sun\"?","options":["fun","sit","top","hot"],"answer":0,"explanation":"\"sun\" (/sʌn/) มีเสียงสัมผัสสระและตัวสะกดตรงกับคำว่า \"fun\" (/fʌn/)"},{"subject":"ภาษาอังกฤษ","grade":"ป.4","topic":"[ต 1.1 ป.4/3] Traffic Signs","difficulty":"easy","question_type":"mcq","question_text":"What does a red octagonal sign with the word \"STOP\" instruct drivers to do?","options":["Go faster","Turn around","Stop the vehicle completely","Park here"],"answer":2,"explanation":"ป้าย STOP สั่งให้ผู้ขับขี่หยุดรถโดยสมบูรณ์ก่อนเพื่อความปลอดภัย"},{"subject":"ภาษาอังกฤษ","grade":"ป.4","topic":"[ต 1.1 ป.4/2] Digraph Sounds: /sh/ and /ch/","difficulty":"medium","question_type":"mcq","question_text":"Which word contains the /tʃ/ sound as in \"chair\"?","options":["ship","chocolate","shoe","fish"],"answer":1,"explanation":"\"chocolate\" ออกเสียงพยัญชนะต้น ch- (/tʃ/) เหมือนคำว่า \"chair\""},{"subject":"ภาษาอังกฤษ","grade":"ป.4","topic":"[ต 1.1 ป.4/4] Understanding Timetables","difficulty":"medium","question_type":"mcq","question_text":"Look at Tom''s timetable: \"09:00 - English, 10:00 - Math, 11:00 - Science, 12:00 - Lunch.\" What subject does Tom study at 10:00?","options":["English","Math","Science","Art"],"answer":1,"explanation":"จากตารางเรียน เวลา 10:00 น. ทอมเรียนวิชาคณิตศาสตร์ (Math)"},{"subject":"ภาษาอังกฤษ","grade":"ป.4","topic":"[ต 1.2 ป.4/1] Greetings and How Are You","difficulty":"easy","question_type":"mcq","question_text":"A: \"Good morning, Tom! How are you today?\"\nB: \"________, thank you. And you?\"","options":["I am 10 years old","I am fine","My name is Tom","I am from Thailand"],"answer":1,"explanation":"เมื่อมีคนถามว่า \"How are you today?\" คำตอบมาตรฐานคือ \"I am fine / I am good, thank you.\""},{"subject":"ภาษาอังกฤษ","grade":"ป.4","topic":"[ต 1.2 ป.4/1] Introductions","difficulty":"easy","question_type":"mcq","question_text":"A: \"Nice to meet you, Lisa.\"\nB: \"____________________\"","options":["Good night","Nice to meet you, too","Goodbye","You are welcome"],"answer":1,"explanation":"เมื่อผู้อื่นพูดว่า \"Nice to meet you.\" ควรตอบกลับว่า \"Nice to meet you, too.\""},{"subject":"ภาษาอังกฤษ","grade":"ป.4","topic":"[ต 1.2 ป.4/2] Asking for Permission","difficulty":"medium","question_type":"mcq","question_text":"Student: \"May I go to the restroom, please?\"\nTeacher: \"________\"","options":["Yes, you may.","No, thank you.","I am sorry.","You are tall."],"answer":0,"explanation":"เมื่อขออนุญาตด้วย \"May I...?\" คุณครูอนุญาตจะตอบว่า \"Yes, you may.\" หรือ \"Sure.\""},{"subject":"ภาษาอังกฤษ","grade":"ป.4","topic":"[ต 1.2 ป.4/2] Offering Help","difficulty":"medium","question_type":"mcq","question_text":"A: \"Can I help you carry these heavy books?\"\nB: \"____________________\"","options":["No, I am not.","Thank you very much. That is very kind of you.","I am hungry.","It is 5 o''clock."],"answer":1,"explanation":"เมื่อมีผู้เสนอความช่วยเหลือและเราต้องการรับ ควรตอบขอบคุณอย่างสุภาพว่า \"Thank you very much.\""},{"subject":"ภาษาอังกฤษ","grade":"ป.4","topic":"[ต 1.2 ป.4/3] Expressing Likes and Dislikes","difficulty":"easy","question_type":"mcq","question_text":"A: \"Do you like apples?\"\nB: \"Yes, ________. They are delicious.\"","options":["I do","I am","I can","I like not"],"answer":0,"explanation":"คำถามที่ขึ้นต้นด้วย \"Do you...?\" เวลาตอบรับแบบสั้นจะใช้ \"Yes, I do.\""},{"subject":"ภาษาอังกฤษ","grade":"ป.4","topic":"[ต 1.2 ป.4/3] Asking About Food Preferences","difficulty":"medium","question_type":"mcq","question_text":"A: \"What is your favorite fruit?\"\nB: \"My favorite fruit is ________.\"","options":["pizza","mango","fried rice","milk"],"answer":1,"explanation":"ผลไม้ (fruit) ในตัวเลือกมีเพียงอย่างเดียวคือ \"mango\" (มะม่วง)"},{"subject":"ภาษาอังกฤษ","grade":"ป.4","topic":"[ต 1.2 ป.4/4] Asking Feelings and Emotions","difficulty":"easy","question_type":"mcq","question_text":"Look at the picture of a boy drinking water after playing sports. How does he feel?","options":["He is thirsty.","He is cold.","He is sleepy.","He is angry."],"answer":0,"explanation":"คนที่ดื่มน้ำหลังเล่นกีฬา คือรู้สึกกระหายน้ำ หรือ \"thirsty\""},{"subject":"ภาษาอังกฤษ","grade":"ป.4","topic":"[ต 1.2 ป.4/4] Expressing Feelings","difficulty":"easy","question_type":"mcq","question_text":"A: \"Why are you smiling?\"\nB: \"Because I am very ________ today. It is my birthday!\"","options":["sad","happy","tired","sick"],"answer":1,"explanation":"ในวันเกิดและกำลังยิ้ม แสดงถึงความรู้สึกมีความสุข หรือ \"happy\""}]'::jsonb, 30, 50, 'ENG401', true);